const GLOSSARY_MAP = new Map();
ABBREVIATIONS_DATA.forEach(item => {
  GLOSSARY_MAP.set(item.abbr.toUpperCase(), item);
});

function getAbbreviationDetails(abbr, lang = "en") {
  if (!abbr) return null;
  const match = GLOSSARY_MAP.get(abbr.trim().toUpperCase());
  if (!match) return null;
  return {
    abbr: match.abbr,
    expansion: match.expansion,
    plain: lang === "te" ? match.plainTe : match.plainEn,
    category: match.category
  };
}

module.exports = {
  ABBREVIATIONS_DATA,
  GLOSSARY_MAP,
  getAbbreviationDetails
};
